def unique_jobs(rows):
    seen = set()
    result = []
    for r in rows:
        source = r.get('source', '')
        source_id = r.get('source_id')
        if source_id is None or source_id == '':
            key = (source, source_id)  # None or '' treated as distinct
        else:
            key = (source, source_id)
        if key not in seen:
            seen.add(key)
            result.append(r.copy())
    return result
